class AppException extends RuntimeException {
    private final String errorCode;
    AppException(String code, String msg) { super(msg); this.errorCode = code; }
    AppException(String code, String msg, Throwable cause) { super(msg, cause); this.errorCode = code; }
    String getErrorCode() { return errorCode; }
}
static void connectDB() throws java.sql.SQLException {
    throw new java.sql.SQLException("Connection timeout");
}
static void loadUser(int id) {
    try {
        connectDB();
    } catch (java.sql.SQLException e) {
        throw new AppException("DB_001", "Failed to load user: " + id, e);
    }
}
try { loadUser(42); }
catch (AppException e) {
    System.out.println(e.getErrorCode() + ": " + e.getMessage());
    System.out.println("Root: " + e.getCause().getMessage());
}

