public class Product {
    private final String name;
    private final double price;
    private       int    stock;
    private final String category;

    public Product(String name, double price, int stock, String category) {
        Objects.requireNonNull(name,     'name must not be null');     // NullPointerException
        Objects.requireNonNull(category, 'category must not be null'); // NullPointerException
        if (name.isBlank())
            throw new IllegalArgumentException('name must not be blank');
        if (price <= 0)
            throw new IllegalArgumentException('price must be positive, got: ' + price);
        if (stock < 0)
            throw new IllegalArgumentException('stock cannot be negative, got: ' + stock);
        if (category.isBlank())
            throw new IllegalArgumentException('category must not be blank');
        this.name = name; this.price = price; this.stock = stock; this.category = category;
    }
}
// Valid: new Product('Laptop', 75000, 10, 'Electronics') — succeeds
// Invalid: new Product(null, 75000, 10, 'Electronics') — NullPointerException: name must not be null
// Invalid: new Product('', 75000, 10, 'Electronics') — IllegalArgumentException: name must not be blank
// Invalid: new Product('Laptop', -500, 10, 'Electronics') — IllegalArgumentException: price must be positive, got: -500.0
// Invalid: new Product('Laptop', 75000, -1, 'Electronics') — IllegalArgumentException: stock cannot be negative, got: -1

