8. What is the output and what fundamental concept does it prove?
static String result = "";
static void level3() {
    result += "3-start ";
    throw new RuntimeException("from level3");
    // result += "3-end "; // unreachable
}
static void level2() {
    result += "2-start ";
    try { level3(); }
    finally { result += "2-finally "; }
    // result += "2-after "; // unreachable if exception propagates
}
static void level1() {
    result += "1-start ";
    try { level2(); }
    catch (RuntimeException e) { result += "1-catch "; }
    result += "1-end ";
}
public static void main(String[] args) {
    level1();
    System.out.println(result);
}
